for (let i = 0; i < done.length && !stage; i++) {
  const r = done[i].result;
  if (r === 'W') wins++;
  else if (r === 'L') losses++;
  else ties++;

  if (i >= swiss) {
    // top cut: one loss and you're out
    if (r === 'L') stage = 'Eliminated';
    else if (i - swiss + 1 >= settings.topCutRounds) stage = 'Champion';
  } else if (losses > settings.lossThreshold) {
    // X-2 is still alive, X-3 is not
    stage = 'Eliminated';
  }
}

